begin;
alter table public.financial_entries add column if not exists work_id uuid,add column if not exists engineering_contract_id uuid,add column if not exists measurement_id uuid;
alter table public.financial_entries add constraint financial_entries_work_fk foreign key(tenant_id,company_id,work_id) references public.works(tenant_id,company_id,id) on delete restrict,add constraint financial_entries_engineering_contract_fk foreign key(tenant_id,company_id,engineering_contract_id) references public.engineering_contracts(tenant_id,company_id,id) on delete restrict,add constraint financial_entries_measurement_fk foreign key(tenant_id,company_id,measurement_id) references public.measurements(tenant_id,company_id,id) on delete restrict;
create index financial_entries_work_idx on public.financial_entries(tenant_id,company_id,work_id) where work_id is not null;create index financial_entries_engineering_contract_idx on public.financial_entries(tenant_id,company_id,engineering_contract_id) where engineering_contract_id is not null;create unique index financial_entries_measurement_unique on public.financial_entries(tenant_id,company_id,measurement_id) where measurement_id is not null;
update public.financial_entries fe set work_id=c.work_id,engineering_contract_id=m.contract_id,measurement_id=m.id from public.measurement_finance_links l join public.measurements m on m.tenant_id=l.tenant_id and m.company_id=l.company_id and m.id=l.measurement_id join public.engineering_contracts c on c.tenant_id=m.tenant_id and c.company_id=m.company_id and c.id=m.contract_id where fe.tenant_id=l.tenant_id and fe.company_id=l.company_id and fe.id=l.financial_entry_id;
create or replace function public.generate_measurement_receivable(p_measurement_id uuid,p_due_date date) returns uuid language plpgsql security invoker set search_path='' as $$declare v_m public.measurements%rowtype;v_contract public.engineering_contracts%rowtype;v_work public.works%rowtype;v_net numeric(18,2);v_entry uuid;v_installment uuid;v_existing uuid;begin if p_due_date is null then raise exception 'due date is required';end if;select * into v_m from public.measurements where id=p_measurement_id for update;if not found or not app_private.can_access_company(v_m.tenant_id,v_m.company_id) then raise exception 'measurement not found or inaccessible';end if;if v_m.status<>'approved' then raise exception 'only approved measurements generate receivables';end if;select financial_entry_id into v_existing from public.measurement_finance_links where tenant_id=v_m.tenant_id and company_id=v_m.company_id and measurement_id=v_m.id;if found then return v_existing;end if;select * into v_contract from public.engineering_contracts where tenant_id=v_m.tenant_id and company_id=v_m.company_id and id=v_m.contract_id;select * into v_work from public.works where tenant_id=v_m.tenant_id and company_id=v_m.company_id and id=v_contract.work_id;select net_amount into v_net from public.measurement_financial_summary where measurement_id=v_m.id;if coalesce(v_net,0)<=0 then raise exception 'measurement net amount must be positive';end if;insert into public.financial_entries(tenant_id,company_id,entry_type,description,counterparty_name,competence_month,notes,created_by,work_id,engineering_contract_id,measurement_id) values(v_m.tenant_id,v_m.company_id,'income','Medição - '||coalesce(v_work.name,'Obra')||' - Contrato '||coalesce(v_contract.contract_number,'s/n'),coalesce(v_contract.client_name,v_work.client_name),v_m.competence,'Gerado automaticamente pela Engenharia. Medição: '||v_m.id::text,(select auth.uid()),v_work.id,v_contract.id,v_m.id) returning id into v_entry;insert into public.financial_installments(tenant_id,company_id,entry_id,installment_number,installment_count,due_date,amount,competence_month) values(v_m.tenant_id,v_m.company_id,v_entry,1,1,p_due_date,v_net,v_m.competence) returning id into v_installment;insert into public.measurement_finance_links(tenant_id,company_id,measurement_id,financial_entry_id,financial_installment_id,linked_by) values(v_m.tenant_id,v_m.company_id,v_m.id,v_entry,v_installment,(select auth.uid()));return v_entry;end$$;
create view public.finance_engineering_traceability with(security_invoker=true) as select fe.tenant_id,fe.company_id,fe.id financial_entry_id,fe.entry_type,fe.description,fe.competence_month,fe.work_id,w.name work_name,fe.engineering_contract_id,c.contract_number,fe.measurement_id,m.competence measurement_competence,i.id installment_id,i.due_date,i.amount receivable_amount,coalesce(sum(s.amount),0)::numeric(18,2) settled_amount,(i.amount-coalesce(sum(s.amount),0))::numeric(18,2) remaining_amount,max(s.settled_on) last_settled_on from public.financial_entries fe left join public.works w on w.tenant_id=fe.tenant_id and w.company_id=fe.company_id and w.id=fe.work_id left join public.engineering_contracts c on c.tenant_id=fe.tenant_id and c.company_id=fe.company_id and c.id=fe.engineering_contract_id left join public.measurements m on m.tenant_id=fe.tenant_id and m.company_id=fe.company_id and m.id=fe.measurement_id left join public.financial_installments i on i.tenant_id=fe.tenant_id and i.company_id=fe.company_id and i.entry_id=fe.id left join public.financial_settlements s on s.tenant_id=i.tenant_id and s.company_id=i.company_id and s.installment_id=i.id where fe.measurement_id is not null group by fe.tenant_id,fe.company_id,fe.id,fe.entry_type,fe.description,fe.competence_month,fe.work_id,w.name,fe.engineering_contract_id,c.contract_number,fe.measurement_id,m.competence,i.id,i.due_date,i.amount;
commit;